func ParsePort(s string) (uint16, error) {
    v, err := strconv.ParseUint(s, 10, 16)
    if err != nil {
        return 0, fmt.Errorf("parse port %q: %w", s, err)
    }
    if v == 0 {
        return 0, fmt.Errorf("port %d: %w", v, ErrOutOfRange)
    }
    return uint16(v), nil
}

